<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use App\Models\{Group,User};use App\Http\Requests\{CreateGroupRequest,AddGroupMemberRequest};use App\Http\Resources\GroupResource;use App\Services\GroupService;use App\Support\ApiResponse;
class GroupController extends Controller { public function __construct(private GroupService $service,private ApiResponse $response){} public function index(Request $r){$u=$r->user();$groups=Group::whereIn('member_ids',[(string)$u->_id])->paginate((int)$r->query('per_page',20));return $this->response->success('Groups retrieved successfully.',GroupResource::collection($groups));} public function store(CreateGroupRequest $r){return $this->response->success('Group created successfully.',new GroupResource($this->service->create($r->validated(),$r->user())),201);} public function show(string $group,Request $r){return $this->response->success('Group retrieved successfully.',new GroupResource($this->service->get($group,$r->user())));} public function update(CreateGroupRequest $r,string $group){$g=$this->service->manage($group,$r->user());$g->update($r->validated());return $this->response->success('Group updated successfully.',new GroupResource($g));} public function destroy(string $group,Request $r){$g=$this->service->manage($group,$r->user());$g->delete();return $this->response->success('Group deleted successfully.');} public function members(string $group,Request $r){$g=$this->service->get($group,$r->user());return $this->response->success('Group members retrieved successfully.',User::whereIn('_id',array_map('strval',$g->member_ids??[]))->get()->map(fn($u)=>['id'=>(string)$u->_id,'name'=>$u->name,'email'=>$u->email]));} public function addMember(AddGroupMemberRequest $r,string $group){$g=$this->service->manage($group,$r->user());return $this->response->success('Member added successfully.',new GroupResource($this->service->add($g,$r->validated()['user_id'])));} public function removeMember(string $group,string $user,Request $r){$g=$this->service->manage($group,$r->user());return $this->response->success('Member removed successfully.',new GroupResource($this->service->remove($g,$user)));} }
